thf-rich-text {
  --border-color: var(--color-neutral-mid-40);
  --border-radius: 18px;
  --border-width: var(--border-width-sm);

  --padding: var(--spacing-xxs);

  --border-color-separator: var(--border-color);
  --border-width-separator: var(--border-width);
  --background-color-toolbar: var(--color-neutral-light-00);

  --background-color-content: var(--color-neutral-light-05);
  --color-content: var(--color-neutral-dark-90);
  --font-family-content: var(--font-family-theme);
  --color-icon: var(--color-neutral-dark-90);
  --color-icon-hover: var(--color-neutral-dark-90);
  --color-icon-active: var(--color-neutral-dark-90);
  --toolbar-disabled-color: #74859a;
  --toolbar-button-size: 44px;
  --toolbar-button-focus-size: 48px;
  --toolbar-button-focus-color: var(--color-neutral-dark-90);

  --border-color-hover: var(--color-neutral-dark-70);

  --border-color-focus: var(--color-action-focus);
  --outline-width-focus: var(--outline-width-focus-aaa, 3px);

  --border-color-error: var(--color-feedback-negative-base);
  --color-error: var(--color-feedback-negative-dark);

  --opacity-disabled: 0.5;
  --background-color-disabled: var(--color-neutral-light-20);

  --min-width: 60.75rem;
  --max-width: 102.25rem;

  --font-size-helper: var(--font-size-sm);
  --color-helper: var(--color-neutral-mid-60);
  --color-label: var(--color-neutral-dark-90);
  --font-weight-label: var(--font-weight-semibold);
}

thf-rich-text[t-size='small'] {
  --toolbar-button-size: 32px;
  --toolbar-button-focus-size: 36px;
}

:root[class*='-dark'] thf-rich-text {
  --background-color-disabled: var(--color-neutral-dark-70);
}
