thf-grid,
thf-grid-detail {
  --background-color: var(--color-neutral-light-00);
  --color: var(--color-neutral-dark-95);

  --font-family: var(--font-family-theme);

  --background-striped-color: var(--color-neutral-light-05);

  --color-line: var(--color-neutral-light-40);

  --background-color-selected: var(--color-brand-01-lightest);

  --background-color-current-row-actions: var(--color-brand-01-lightest);

  --background-color-edited: var(--color-feedback-warning-lightest);
  --border-color-edited: var(--color-feedback-warning-base);

  --background-color-included: var(--color-feedback-warning-lightest);
  --border-color-included: var(--color-feedback-warning-base);

  --border-color-current-row-actions: var(--color-brand-01-lighter);

  --background-color-removed: var(--background-color-removed);

  --background-color-headline: var(--color-neutral-light-10);

  --font-weight-headline: var(--font-weight-bold);

  --color-hover: var(--color-action-hover);
  --background-color-hover: var(--color-brand-01-lighter);

  --outline-color-focused: var(--color-action-focus);

  --color-actived: var(--color-neutral-dark-90);
  --background-color-actived: var(--color-brand-01-light);

  --color-disabled: var(--color-neutral-mid-40);
  --letter-spacing-toolbar-title: 0.017rem;

  --border-color: var(--color-neutral-light-10);
  --border-radius: var(--border-radius-md);
  --border-width: var(--border-width-sm);

  --border-color-toolbar: var(--border-color);
  --border-width-toolbar: var(--border-width);

  --font-family-toolbar-title: var(--font-family);
  --font-size-toolbar-title: var(--font-size-md);
  --font-weight-toolbar-title: var(--font-weight-bold);

  --font-family-empty-state-body-subtitle: var(--font-family);
  --font-size-empty-state-body-subtitle: var(--font-size-md);
  --font-weight-empty-state-body-subtitle: var(--font-weight-bold);

  --font-family-empty-state-body-message: var(--font-family);
  --font-size-empty-state-body-message: var(--font-size-default);
  --font-weight-empty-state-body-message: var(--font-weight-normal);

  /* Repassa os estilos das bordas do thf-grid para o po-container interno */
  --border-color-container: var(--border-color);
  --border-radius-container: var(--border-radius);
  --border-width-container: var(--border-width);

  --border-color-aggregates: var(--border-color);
  --border-width-aggregates: var(--border-width);
}

[data-a11y='AA'].totvs-light-AA thf-grid,
[data-a11y='AA'].totvs-light-AA thf-grid-detail {
  --background-striped-color: var(--color-neutral-light-10);
  --background-color-headline: var(--color-neutral-light-20);
}

:is([data-a11y='AAA'].totvs-dark-AAA, [data-a11y='AA'].totvs-dark-AA) :is(thf-grid, thf-grid-detail) {
  --background-striped-color: var(--color-brand-01-lighter);
}

[data-a11y='AA'] thf-grid,
[data-a11y='AA'] thf-grid-detail {
  --font-size-toolbar-title: var(--font-size-default);

  --font-size-empty-state-body-subtitle: var(--font-size-default);

  --font-size-empty-state-body-message: var(--font-size-sm);
}

thf-grid po-container {
  --border-color: var(--border-color-container);
  --border-radius: var(--border-radius-container);
  --border-width: var(--border-width-container);
}

kendo-grid button:not(.po-button),
kendo-grid .k-button,
kendo-grid kendo-button {
  --border-width: 1px;
}

.k-button:is(:focus) {
  outline-width: 0px !important;
}

.k-button:is(:focus-visible) {
  outline-width: 1px !important;
}

.k-button-text {
  font-weight: 400;
}

.k-grid-footer {
  border-top: var(--border-width-aggregates) solid var(--border-color-aggregates);
  background-color: var(--background-color) !important;
}

.k-grid-footer-wrap {
  border-color: rgb(0 0 0 / 0%);
}

.k-grid-group-footer-aggregate,
.k-grid-footer-aggregate {
  font-weight: var(--font-weight-headline);
}

kendo-grid.k-grid .k-table-alt-row .k-group-cell:not(.k-table-th),
kendo-grid.k-grid .k-table-alt-row:hover .k-group-cell:not(.k-table-th) {
  background-color: var(--background-striped-color);
}

kendo-grid[t-stripe='false'].k-grid .k-grouping-row {
  --background-color-groupable: var(--background-color);
}

/* Aplica background às células das linhas marcadas como não listradas */
kendo-grid.k-grid tr.not-striped > .k-table-td,
kendo-grid.k-grid tr.not-striped.k-table-alt-row .k-group-cell:not(.k-table-th),
kendo-grid.k-grid tr.not-striped > .k-table-td.k-grid-content-sticky.k-touch-action-auto,
kendo-grid.k-grid tr.not-striped > .k-table-td.k-grid-content-sticky.k-touch-action-auto:hover,
kendo-grid.k-grid tr.not-striped > .k-table-td.k-grid-content-sticky::before,
kendo-grid.k-grid tr.not-striped > .k-table-td.k-grid-content-sticky.k-touch-action-auto::before {
  background-color: var(--background-color);
}

/* Aplica borda nas células das linhas não listradas, exceto na última linha */
kendo-grid.k-grid .k-table-row:not(.k-detail-row).not-striped:not(:last-of-type) .k-table-td {
  border-bottom: solid;
  border-bottom-color: var(--color-neutral-mid-40);
  border-bottom-width: var(--border-width-sm);
}

thf-grid .toolbar-edit-row-actions po-field-container > .po-field-container > .po-field-container-content {
  --padding: 0px;
}
thf-grid
  .toolbar-edit-row-actions
  po-field-container
  > .po-field-container
  > po-field-container-bottom
  > .po-field-container-bottom:empty {
  padding-bottom: 0px;
}

tfoot tr.k-footer-template td {
  background-color: var(--background-color) !important;
}

kendo-tooltip {
  --color: var(--color-neutral-dark-80);
  --border-radius: var(--border-radius-md);
  --font-family: var(--font-family-theme);
  --text-color: var(--color-neutral-light-00);
}

.k-tooltip {
  background-color: var(--color);
  border-radius: var(--border-radius);
  box-shadow: var(--shadow-tooltip-shadow-balloon);
  max-width: 15rem;
  padding: var(--po-density-floating-padding, var(--default-spacing-squish-xs, var(--spacing-squish-md)));
  line-height: var(--line-height-md);
  font-size: var(--font-size-default);
  font-family: var(--font-family);
  opacity: 0.9;
}

.k-tooltip .k-tooltip-content {
  font-family: var(--font-family), sans-serif;
  font-size: 14px;
  line-height: 24px;
  color: var(--text-color);
  font-style: normal;
  font-weight: var(--font-weight-normal);
  font-size: var(--font-size-sm);
  white-space: normal;
  word-wrap: break-word;
  text-align: left;
  opacity: 0.9;
}
