thf-treelist [type='checkbox'],
thf-treelist [type='radio'] {
  --border-color: var(--color-neutral-dark-70);
  --color-unchecked: var(--color-neutral-light-00);

  --color-checked: var(--color-action-default);

  --color-hover: var(--color-action-hover);
  --shadow-color-hover: var(--color-brand-01-lighter);

  --outline-color-focused: var(--color-action-focus);

  --color-unchecked-disabled: var(--color-action-disabled);

  --color-checked-disabled: var(--color-neutral-dark-70);

  --width-sm: 16px;
  --width-md: 24px;

  --offset-checked: 6px;

  --circle-width-sm: calc(var(--width-sm) - 8px);
  --circle-width-md: calc(var(--width-md) - 12px);

  --background-radial-sm: radial-gradient(
    var(--circle-width-sm) circle at center,
    var(--color-checked) 50%,
    rgba(0, 0, 0, 0) 57%
  );
  --background-radial-sm-disabled: radial-gradient(
    var(--circle-width-sm) circle at 6px 6px,
    var(--color-checked-disabled) 50%,
    rgba(0, 0, 0, 0) 57%
  );
  --background-radial-md: radial-gradient(
    var(--circle-width-md) circle at center,
    var(--color-checked) 50%,
    rgba(0, 0, 0, 0) 57%
  );
  --background-radial-md-disabled: radial-gradient(
    var(--circle-width-md) circle at 10px 10px,
    var(--color-checked-disabled) 50%,
    rgba(0, 0, 0, 0) 57%
  );
  display: inline-block;
}

thf-treelist #selectAllCheckboxId {
  position: absolute;
}
