thf-splitter {
  /* SPLITTER TRACK */
  --background-track: var(--color-neutral-light-10);

  /* RESIZABLE TRIGGER */
  --color: var(--color-action-default);
  --background-color: var(--color-neutral-light-00);
  --box-shadow: var(--shadow-sm);

  /* HOVER */
  --background-color-hover: var(--color-brand-01-lighter);
  --color-hover: var(--color-brand-01-darkest);

  /* PRESSED */
  --background-color-pressed: var(--color-brand-01-light);
  --color-pressed: var(--color-brand-01-darkest);
}

[data-a11y='AA'] thf-splitter kendo-splitter.k-splitter kendo-splitter-bar.k-splitbar {
  margin: var(--spacing-xs);
  .k-resize-handle {
    width: var(--target-size-aa);
    height: var(--target-size-aa);
  }
}

thf-splitter {
  height: inherit;

  & kendo-splitter.k-splitter {
    border: none;
    background: var(--color-transparent);

    &[disabled='true'] > kendo-splitter-bar.k-splitbar {
      pointer-events: none;
      .k-resize-handle {
        display: none;
      }

      &.k-splitbar-vertical {
        height: 6px;
      }

      &.k-splitbar-horizontal {
        width: 6px;
      }
    }

    & kendo-splitter-bar.k-splitbar {
      background: var(--color-transparent);
      height: auto;
      width: auto;
      margin: var(--spacing-sm);

      &.k-splitbar-vertical {
        &::before {
          width: 100%;
          height: 0.375rem;
        }
      }

      &.k-splitbar-horizontal {
        &::before {
          width: 0.375rem;
          height: 100%;
        }
      }

      &::before {
        background: var(--background-track);
        content: ' ';
        position: absolute;
      }

      .k-resize-handle {
        width: var(--target-size-aaa);
        height: var(--target-size-aaa);
        border-radius: var(--border-radius-pill);
        display: flex;

        box-shadow: var(--box-shadow);
        background: var(--background-color);
        color: var(--color);

        i {
          font-size: var(--font-size-lg);
        }
      }

      &:hover .k-resize-handle,
      &:focus .k-resize-handle {
        background: var(--background-color-hover);
        color: var(--color-hover);
      }

      &:active .k-resize-handle {
        background: var(--background-color-pressed);
        color: var(--color-pressed);
      }

      &:hover {
        background: transparent;
      }
    }

    /* fix po-page-content height  */
    .po-page-content {
      box-sizing: border-box;
      display: grid;
      align-content: baseline;
    }

    .po-page-content > * {
      flex: 1;
    }
  }
}

/**
 * Correção nos cenarios onde está sendo utilizado o po-menu com o splitter ou com o po-page-default
 */
.po-wrapper {
  &.po-collapsed-menu {
    & > thf-splitter {
      margin-left: var(--collapsed-menu-width);
      width: calc(100% - var(--collapsed-menu-width));
    }
  }

  /* CENARIO: THF-SPLITTER > PO-PAGE-DEFAULT */
  & > thf-splitter {
    margin-left: var(--menu-width);
    width: calc(100% - var(--menu-width));
    display: flex;
    height: 100vh;

    .po-page {
      margin-left: 0px !important;
      width: 100% !important;
      height: auto;
    }
  }

  /* CENARIO: PO-PAGE-DEFAULT > THF-SPLITTER */
  & .po-page .po-page-content thf-splitter {
    display: flex;

    /* CENARIO: PO-PAGE-DEFAULT > THF-SPLITTER > PO-PAGE-DEFAULT*/
    .po-page {
      margin-left: 0px !important;
      width: 100% !important;
      height: auto;
    }
  }
}
